-- @case 1: two phones give two rows (unknown phone type is NULL); no email or a NULL email is NULL; Title '' kept; a missing contact type or person drops the contact; a store without contacts is not listed
BEGIN;
DELETE FROM person.business_entity_contact;
DELETE FROM person.contact_type;
DELETE FROM person.email_address;
DELETE FROM person.person;
DELETE FROM person.person_phone;
DELETE FROM person.phone_number_type;
DELETE FROM sales.store;
INSERT INTO person.business_entity_contact ("BusinessEntityID", "PersonID", "ContactTypeID") VALUES
  ('1', '1', '1'),
  ('1', '2', '2'),
  ('1', '3', '2'),
  ('1', '4', '99'),
  ('1', '5', '1');
INSERT INTO person.contact_type ("ContactTypeID", "Name") VALUES
  ('1', 'Owner'),
  ('2', 'Purchasing Agent');
INSERT INTO person.email_address ("BusinessEntityID", "EmailAddress") VALUES
  ('2', 'ann@example.com'),
  ('3', NULL);
INSERT INTO person.person ("BusinessEntityID", "Title", "FirstName", "MiddleName", "LastName", "Suffix", "EmailPromotion") VALUES
  ('1', NULL, 'First1', NULL, 'Last1', NULL, '0'),
  ('2', '', 'Ann ', 'B', 'Last2', 'Jr.', '0'),
  ('3', NULL, 'First3', NULL, 'Last3', NULL, '2'),
  ('4', NULL, 'First4', NULL, 'Last4', NULL, '0');
INSERT INTO person.person_phone ("BusinessEntityID", "PhoneNumber", "PhoneNumberTypeID") VALUES
  ('1', '555-0100', '1'),
  ('1', '555-0199', '9'),
  ('3', '555-0300', '1');
INSERT INTO person.phone_number_type ("PhoneNumberTypeID", "Name") VALUES
  ('1', 'Cell');
INSERT INTO sales.store ("BusinessEntityID", "Name") VALUES
  ('1', 'First store'),
  ('2', 'Lonely store');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM sales.v_store_with_contacts;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Name', 'ContactType', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 two phones give two rows (unknown phone type is NULL); no email or a NULL email is NULL; Title kept;…', got, ARRAY['BusinessEntityID', 'Name', 'ContactType', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'PhoneNumber', 'PhoneNumberType', 'EmailAddress', 'EmailPromotion']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'First store', 'Owner', NULL, 'First1', NULL, 'Last1', NULL, '555-0100', 'Cell', NULL, '0'),
  ('1', 'First store', 'Owner', NULL, 'First1', NULL, 'Last1', NULL, '555-0199', NULL, NULL, '0'),
  ('1', 'First store', 'Purchasing Agent', '', 'Ann ', 'B', 'Last2', 'Jr.', NULL, NULL, 'ann@example.com', '0'),
  ('1', 'First store', 'Purchasing Agent', NULL, 'First3', NULL, 'Last3', NULL, '555-0300', 'Cell', NULL, '2');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 two phones give two rows (unknown phone type is NULL); no email or a NULL email is NULL; Title kept;…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
